        then assign previousPressed := true;
      } else {
        first start;
        then assign previousPressed := io_2;
      }
    }
    out attribute io_1 : Real = (if manualMode ? frozenBrightnessValue else (if ((io_0) >= (1023.0)) ? 255.0 else (if ((io_0) <= (0.0)) ? 0.0 else io_0 * 255.0 / 1023.0)));
